def two_sum(nums, target):
    index_by_value = {}
    for i, value in enumerate(nums):
        need = target - value
        if need in index_by_value:
            return [index_by_value[need], i]
        index_by_value[value] = i
    return []

def pair_exists(values, target):
    left, right = 0, len(values) - 1  # values is sorted
    while left < right:
        total = values[left] + values[right]
        if total == target:
            return True
        if total < target:
            left += 1
        else:
            right -= 1
    return False

def max_sum_k(nums, k):
    if k <= 0 or k > len(nums):
        return None
    window = sum(nums[:k])
    best = window
    for right in range(k, len(nums)):
        window += nums[right] - nums[right - k]
        best = max(best, window)
    return best

def lower_bound(a, target):
    lo, hi = 0, len(a)  # search [lo, hi)
    while lo < hi:
        mid = lo + (hi - lo) // 2
        if a[mid] < target:
            lo = mid + 1
        else:
            hi = mid
    return lo

def next_greater(nums):
    answer = [-1] * len(nums)
    stack = []  # indices with decreasing values
    for i, value in enumerate(nums):
        while stack and nums[stack[-1]] < value:
            answer[stack.pop()] = value
        stack.append(i)
    return answer

from collections import deque

def distances(graph, start):
    dist = {start: 0}
    queue = deque([start])
    while queue:
        node = queue.popleft()
        for neighbor in graph[node]:
            if neighbor not in dist:
                dist[neighbor] = dist[node] + 1
                queue.append(neighbor)
    return dist

def min_cost_climb(cost):
    prev2, prev1 = 0, 0
    for i in range(2, len(cost) + 1):
        current = min(prev1 + cost[i - 1], prev2 + cost[i - 2])
        prev2, prev1 = prev1, current
    return prev1

