    prefix = [0]
    for value in values:
        prefix.append(prefix[-1] + value)
    return [prefix[r] - prefix[l] for l, r in queries]  # [l, r)

def min_max_load(tasks, workers):
    def feasible(limit):
        used, load = 1, 0
        for task in tasks:
            if load + task > limit:
                used += 1
                load = 0
            load += task
        return used <= workers

    lo, hi = max(tasks), sum(tasks)  # positive tasks
    while lo < hi:
        mid = lo + (hi - lo) // 2
        if feasible(mid):
            hi = mid
        else:
            lo = mid + 1
    return lo

def max_nonoverlap(intervals):
    intervals.sort(key=lambda item: item[1])
    count, end = 0, float('-inf')
    for start, finish in intervals:
        if start >= end:
            count += 1
            end = finish
    return count

def zero_one_knapsack(items, capacity):
    dp = [0] * (capacity + 1)
    for weight, value in items:
        for c in range(capacity, weight - 1, -1):
            dp[c] = max(dp[c], dp[c - weight] + value)
    return dp[capacity]

from collections import deque

def topo_order(graph, indegree):
    queue = deque(v for v, d in enumerate(indegree) if d == 0)
    order = []
    while queue:
        v = queue.popleft()
        order.append(v)
        for nxt in graph[v]:
            indegree[nxt] -= 1
            if indegree[nxt] == 0:
                queue.append(nxt)
    return order if len(order) == len(graph) else None

def gcd(a, b):
    while b:
        a, b = b, a % b
    return abs(a)

def lcm(a, b):
    return 0 if a == 0 or b == 0 else abs((a // gcd(a, b)) * b)

